actions.script:
let parsed = {}
try { parsed = JSON.parse(String(ec.web.secureRequestParameters.resultJson || '{}')) } catch (e) { parsed = {} }
resultColumns = Array.isArray(parsed.columns) ? parsed.columns.map(String) : []
resultRecords = Array.isArray(parsed.records) ? parsed.records.slice(0, 100000) : []
// a sheet name has none of the characters Excel refuses in one
sheetName = String(parsed.name || 'Result').replace(/[\x5b\x5d\x3a*?\/\\]/g, ' ').substring(0, 31) || 'Result'

render-mode.text:
${(() => {
            sri.xlsxSheet(sheetName)
            for (const column of resultColumns) sri.xlsxHeader(column)
            for (const record of resultRecords) {
                for (let index = 0; index < resultColumns.length; index++) {
                    const value = Array.isArray(record) ? record[index] : null
                    sri.xlsxCell([value == null ? '' : typeof value === 'object' ? JSON.stringify(value) : value], [''], false, typeof value === 'number')
                }
                sri.xlsxEndRow()
            }
            return ''
        })()}
